proof
  show "f -` A \<subseteq> inv f ` A"
    using assms by (blast intro: bij_is_inj [THEN inv_into_f_f, symmetric])
  show "inv f ` A \<subseteq> f -` A"
    using assms by (auto simp add: bij_is_surj [THEN surj_f_inv_f])
qed

